r="body">Message *</label><textarea id="body" name="body" class="form-textarea" rows="8" placeholder="Enter your announcement message here..." required></textarea></div><div class="form-group"><label class="form-label" for="audience">Audience *</label><select id="audience" name="audience" class="form-select"><option value="students">Students Only</option><option value="supervisors">Supervisors Only</option><option value="all">All (Students & Supervisors)</option></select></div><button type="submit" class="btn btn-primary"><svg style="width:20px;height:20px;" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M10 2v16M2 10h16" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>Publish Announcement</button></form></div><div><div class="section-head" style="margin-top:var(--space-8);margin-bottom:var(--space-4);"><div class="section-head__title">Recent Announcements</div><div class="section-head__sub">Latest <?php echo count($announcements); ?> announcements (up to 50 total)</div></div><?php if (empty($announcements)): ?><div class="empty-state">📢 No announcements yet. Create one above to get started!</div><?php else: ?><div class="announcements-list"><?php foreach ($announcements as $a): ?><div class="announcement-item"><div class="announcement-title"><?php echo h($a['title']); ?></div><div class="announcement-meta"><span class="announcement-badge"><?php $audienceLabel=match($a['audience']){'students'=>'👥 Students','supervisors'=>'👔 Supervisors','all'=>'📢 All Users',default=>h($a['audience'])};echo $audienceLabel; ?></span><span><?php echo h($a['created_at']); ?></span><?php if (!$a['is_active']): ?><span style="color:#999;font-style:italic;">(Inactive)</span><?php endif; ?></div><div class="announcement-body"><?php echo h($a['body']); ?></div></div><?php endforeach; ?></div><?php endif; ?></div></div></div></div></body></html>
